require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))
return function(list, callback, p)
	local count = #list
	local result = {}
	local v = 1

	if p == nil then
		for i = 1, count do
			local v2 = list[i]

			if not (v2 ~= nil and callback(v2, i, list)) then
				continue
